// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count how many occur in a full 400-year cycle.

// Earliest Friday the 13th
var date = new DateTime(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");

// Count Friday the 13ths in one 400-year cycle (0001-01-13 through 0400-12-13)
int count = 0;
var d = new DateTime(1, 1, 13);
var end = new DateTime(400, 12, 31);
while (d <= end)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: which day-of-week is the 13th most likely to fall on?
var dayCounts = new int[7];
d = new DateTime(1, 1, 13);
while (d <= end)
{
    dayCounts[(int)d.DayOfWeek]++;
    d = d.AddMonths(1);
}

Console.WriteLine("\n13th falls on each day (400-year cycle):");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-9}: {dayCounts[(int)dow]}");
EOF
dotnet /tmp/friday13.cs

